examples.code:
select tc, count(*) as runs,
       round(100.0 * sum(ok) / count(*), 1) as pass_pct,
       count(distinct case when mixed then build end) as flaky_builds
from (select tc, build, ok,
             min(ok) over (partition by tc, build)
               <> max(ok) over (partition by tc, build) as mixed
      from run)
group by tc order by flaky_builds desc, tc;
